questionvariables.text:
/* Randomise between two valid axes of a triangular prism.
   axis_type = 1 : axis through the centres of the triangular faces.
   axis_type = 2 : one of the three axes through the centres of opposite rectangular faces.
*/

axis_type : rand(2)+1;

/* Teacher answers */

order_sym :
if axis_type=1 then 3
else 2;

axis_name :
if axis_type=1 then
"The axis passes through the centres of the triangular faces."
else
"The axis passes through the centres of a pair of opposite rectangular faces.";

angle_rot : 360/order_sym;

/* Teacher answers */

ta1 : order_sym;
ta2 : angle_rot;
